    return `<div style="width:${size}px; height:${size}px; border-radius:${r}px; background:${on ? INK : CARD}; box-shadow:${on ? 'none' : `0 0 0 1.5px ${LINE}`}; display:flex; align-items:center; justify-content:center;"><svg width="${size}" height="${size}" viewBox="0 0 ${size} ${size}"><path d="${path}" fill="none" stroke="${stroke}" stroke-width="${size > 40 ? 3 : 2.2}" stroke-linecap="round"></path></svg></div>`;
