  const sea = (y = 176) => `<path d="M14 ${y} H378" stroke="${MID}" stroke-width="1.5" stroke-linecap="round"></path><path d="M30 ${y + 10} q11 -6 22 0 t22 0 t22 0 M250 ${y + 10} q11 -6 22 0 t22 0 t22 0 M70 ${y + 22} q11 -6 22 0 t22 0 M224 ${y + 22} q11 -6 22 0 t22 0 t22 0 M120 ${y + 32} q11 -6 22 0 t22 0 t22 0 t22 0" fill="none" stroke="${DIM}" stroke-width="2.2" stroke-linecap="round"></path>`;
  const star = (x, y, r, c = INK) => `<path d="M${x} ${y - r} Q${x} ${y} ${x + r} ${y} Q${x} ${y} ${x} ${y + r} Q${x} ${y} ${x - r} ${y} Q${x} ${y} ${x} ${y - r} Z" fill="${c}"></path>`;
