  const cloud = (x, y, s = 1, c = DIM) => `<g fill="${c}"><circle cx="${x}" cy="${y}" r="${9 * s}"></circle><circle cx="${x + 12 * s}" cy="${y - 5 * s}" r="${12 * s}"></circle><circle cx="${x + 26 * s}" cy="${y}" r="${9 * s}"></circle><rect x="${x - 2 * s}" y="${y}" width="${30 * s}" height="${9 * s}" rx="${4.5 * s}"></rect></g>`;
